-- Managed CMS imports are public configuration references, never credentials.
CREATE TABLE IF NOT EXISTS analytics.website_consent_bindings (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 unit bigint NOT NULL REFERENCES public.units(id) ON DELETE CASCADE,
 website_origin text NOT NULL,
 platform text NOT NULL CHECK(platform IN ('wordpress','joomla','wix','html')),
 provider_config jsonb NOT NULL,
 version bigint NOT NULL CHECK(version>0),
 enabled boolean NOT NULL DEFAULT false,
 confirmed_revision text,
 confirmed_by uuid REFERENCES auth.users(id),
 confirmed_at timestamptz,
 UNIQUE(unit,website_origin)
);
ALTER TABLE analytics.website_consent_bindings DROP CONSTRAINT IF EXISTS website_consent_bindings_platform_check;
ALTER TABLE analytics.website_consent_bindings ADD CONSTRAINT website_consent_bindings_platform_check CHECK(platform IN ('wordpress','joomla','wix','html'));
ALTER TABLE analytics.website_consent_bindings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON analytics.website_consent_bindings FROM PUBLIC,anon,authenticated,service_role;

-- One semantic notice owner for admin exports and public form policy.
CREATE OR REPLACE FUNCTION public.unit_measurement_consent_scope_internal(p_unit bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT jsonb_build_object('organization',u.organization,'unit',u.id,'consentRevision',md5(jsonb_build_array(1,u.organization,u.id,u.data->'measurement_gtm_container',
   u.data->'measurement_scripts',u.data->'measurement_privacy_url',u.data->'measurement_consent_title',
   u.data->'measurement_consent_text',coalesce(u.data->'measurement_consent_version','1'::jsonb),
   r.runtime_profile,r.collector_origins,jsonb_build_array('analytics','marketing'))::text))
 FROM public.units u LEFT JOIN analytics.unit_runtime r ON r.unit=u.id WHERE u.id=p_unit;
$$;
REVOKE ALL ON FUNCTION public.unit_measurement_consent_scope_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.website_consent_binding_effective_internal(p_binding analytics.website_consent_bindings)
RETURNS boolean LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT coalesce(b.enabled AND b.confirmed_revision=public.unit_measurement_consent_scope_internal(u.id)->>'consentRevision'
  AND u.data->'measurement_consent_bridge'='true'::jsonb
  AND u.data->'measurement_enabled'='true'::jsonb
  AND org.data->'FORM_MEASUREMENT_ENABLED'='true'::jsonb AND p.enabled
  AND b.website_origin=ANY(r.parent_origins)
  AND coalesce(u.data->'measurement_websites','[]'::jsonb) ? b.website_origin,false)
 FROM public.units u JOIN public.organizations org ON org.id=u.organization
 LEFT JOIN analytics.organization_policy p ON p.organization=org.id
 LEFT JOIN analytics.unit_runtime r ON r.unit=u.id
 CROSS JOIN LATERAL (SELECT (p_binding).*) b WHERE u.id=b.unit;
$$;
REVOKE ALL ON FUNCTION public.website_consent_binding_effective_internal(analytics.website_consent_bindings) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.website_consent_bindings_policy_internal(p_unit bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'version',b.version,'websiteOrigin',b.website_origin,
  'effective',public.website_consent_binding_effective_internal(b)) ORDER BY b.website_origin),'[]'::jsonb)
 FROM analytics.website_consent_bindings b WHERE b.unit=p_unit;
$$;
REVOKE ALL ON FUNCTION public.website_consent_bindings_policy_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Validate provider inputs once, at the authoritative write boundary. Category
-- bounds count UTF-16 code units, matching the existing JavaScript CMP adapter.
CREATE OR REPLACE FUNCTION public.normalize_website_consent_provider_internal(p_config jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
DECLARE provider text:=p_config->>'provider'; a text; m text; cutoff text; n numeric;
BEGIN
 IF jsonb_typeof(p_config) IS DISTINCT FROM 'object' THEN RAISE invalid_parameter_value USING MESSAGE='invalid_consent_provider'; END IF;
 IF provider='complianz' THEN
  IF jsonb_typeof(p_config->'policyId') IS DISTINCT FROM 'string' OR (p_config->>'policyId') !~ '^[1-9][0-9]{0,15}$' THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid_complianz_policy'; END IF;
  RETURN jsonb_build_object('provider',provider,'policyId',p_config->>'policyId');
 ELSIF provider='cookieconsent' THEN
  a:=p_config#>>'{categories,analytics}'; m:=p_config#>>'{categories,marketing}';
  IF jsonb_typeof(p_config->'revision') IS DISTINCT FROM 'number' OR (p_config->>'revision') !~ '^[1-9][0-9]*$'
   OR (p_config->>'revision')::numeric>9007199254740991 OR a IS NULL OR m IS NULL OR a=m
   OR jsonb_typeof(p_config#>'{categories,analytics}') IS DISTINCT FROM 'string'
   OR jsonb_typeof(p_config#>'{categories,marketing}') IS DISTINCT FROM 'string'
   OR length(a)=0 OR length(m)=0
   OR (SELECT coalesce(sum(CASE WHEN ascii(c)>65535 THEN 2 ELSE 1 END),0) FROM regexp_split_to_table(a,'') c)>128
   OR (SELECT coalesce(sum(CASE WHEN ascii(c)>65535 THEN 2 ELSE 1 END),0) FROM regexp_split_to_table(m,'') c)>128 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid_cookieconsent_mapping'; END IF;
  RETURN jsonb_build_object('provider',provider,'revision',(p_config->>'revision')::bigint,'categories',jsonb_build_object('analytics',a,'marketing',m));
 ELSIF provider IN ('cookiebot','wix') THEN
  cutoff:=p_config->>'consentValidFrom';
  IF (provider='cookiebot' AND (jsonb_typeof(p_config->'cbid') IS DISTINCT FROM 'string' OR (p_config->>'cbid') !~* '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'))
   OR cutoff IS NULL OR cutoff !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
   OR to_char(cutoff::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>cutoff
   OR jsonb_typeof(p_config->'maxAgeSeconds') IS DISTINCT FROM 'number' OR (p_config->>'maxAgeSeconds') !~ '^[1-9][0-9]*$'
   OR (p_config->>'maxAgeSeconds')::numeric>31536000 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid_cookiebot_mapping'; END IF;
  RETURN jsonb_build_object('provider',provider,'consentValidFrom',cutoff,'maxAgeSeconds',(p_config->>'maxAgeSeconds')::bigint)
   ||CASE WHEN provider='cookiebot' THEN jsonb_build_object('cbid',lower(p_config->>'cbid')) ELSE '{}'::jsonb END;
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unsupported_consent_provider';
END $$;
REVOKE ALL ON FUNCTION public.normalize_website_consent_provider_internal(jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_unit_website_consent_bindings(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN RAISE insufficient_privilege; END IF;
 RETURN public.unit_measurement_consent_scope_internal(p_unit)||jsonb_build_object('bindings',
  coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'websiteOrigin',b.website_origin,'platform',b.platform,
   'providerConfig',b.provider_config,'version',b.version,'confirmedRevision',b.confirmed_revision,
   'state',CASE WHEN NOT b.enabled THEN CASE WHEN b.confirmed_revision IS NULL THEN 'draft' ELSE 'disabled' END
     WHEN NOT coalesce(r.parent_origins @> ARRAY[b.website_origin],false) THEN 'approval_required'
     WHEN b.confirmed_revision IS DISTINCT FROM public.unit_measurement_consent_scope_internal(p_unit)->>'consentRevision' THEN 'confirmation_required'
     WHEN public.website_consent_binding_effective_internal(b) THEN 'ready' ELSE 'unavailable' END)
    ORDER BY b.website_origin) FROM analytics.website_consent_bindings b LEFT JOIN analytics.unit_runtime r ON r.unit=b.unit WHERE b.unit=p_unit),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.get_unit_website_consent_bindings(bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_unit_website_consent_bindings(bigint) TO authenticated;

-- A Unit lock serializes authoring with the canonical Unit aggregate save.
-- Version zero means absent. Every write advances the version, including off.
CREATE OR REPLACE FUNCTION public.save_unit_website_consent_binding(p_unit bigint,p_website_origin text,p_platform text,
 p_provider_config jsonb,p_expected_version bigint,p_expected_consent_revision text,p_confirm boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE u public.units; b analytics.website_consent_bindings; scope jsonb; config jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN RAISE insufficient_privilege; END IF;
 SELECT * INTO STRICT u FROM public.units WHERE id=p_unit FOR UPDATE;
 IF p_website_origin IS NULL OR length(p_website_origin)>2048 OR NOT coalesce(u.data->'measurement_websites','[]'::jsonb) ? p_website_origin
  OR p_platform IS NULL OR p_platform NOT IN ('wordpress','joomla','wix','html') OR p_confirm IS NULL THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid_website_binding'; END IF;
 -- Use the canonical exact-origin validation, rather than accepting URLs.
 PERFORM public.validate_configuration_value_internal_v1(jsonb_build_array(p_website_origin),public.configuration_settings_contract_internal_v1()#>'{unit,measurement_websites}');
 scope:=public.unit_measurement_consent_scope_internal(p_unit);
 SELECT * INTO b FROM analytics.website_consent_bindings WHERE unit=p_unit AND website_origin=p_website_origin FOR UPDATE;
 IF p_expected_version IS DISTINCT FROM coalesce(b.version,0) OR p_expected_consent_revision IS DISTINCT FROM scope->>'consentRevision' THEN
  RAISE serialization_failure USING MESSAGE='website_consent_conflict'; END IF;
 config:=public.normalize_website_consent_provider_internal(p_provider_config);
 INSERT INTO analytics.website_consent_bindings(unit,website_origin,platform,provider_config,version,enabled,confirmed_revision,confirmed_by,confirmed_at)
 VALUES(p_unit,p_website_origin,p_platform,config,1,p_confirm,CASE WHEN p_confirm THEN scope->>'consentRevision' END,
  CASE WHEN p_confirm THEN auth.uid() END,CASE WHEN p_confirm THEN clock_timestamp() END)
 ON CONFLICT(unit,website_origin) DO UPDATE SET platform=excluded.platform,provider_config=excluded.provider_config,
  version=analytics.website_consent_bindings.version+1,enabled=excluded.enabled,confirmed_revision=excluded.confirmed_revision,
  confirmed_by=excluded.confirmed_by,confirmed_at=excluded.confirmed_at;
 RETURN public.get_unit_website_consent_bindings(p_unit);
END $$;
REVOKE ALL ON FUNCTION public.save_unit_website_consent_binding(bigint,text,text,jsonb,bigint,text,boolean) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_unit_website_consent_binding(bigint,text,text,jsonb,bigint,text,boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.disable_unit_website_consent_binding(p_binding uuid,p_expected_version bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint;
BEGIN
 SELECT unit INTO un FROM analytics.website_consent_bindings WHERE id=p_binding;
 IF auth.uid() IS NULL OR NOT coalesce(public.can_manage_unit_configuration(un),false) THEN RAISE insufficient_privilege; END IF;
 PERFORM 1 FROM public.units WHERE id=un FOR UPDATE;
 UPDATE analytics.website_consent_bindings SET enabled=false,version=version+1 WHERE id=p_binding AND version=p_expected_version;
 IF NOT FOUND THEN RAISE serialization_failure USING MESSAGE='website_consent_conflict'; END IF;
 RETURN public.get_unit_website_consent_bindings(un);
END $$;
REVOKE ALL ON FUNCTION public.disable_unit_website_consent_binding(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.disable_unit_website_consent_binding(uuid,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.export_unit_website_consent_binding(p_binding uuid,p_expected_version bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b analytics.website_consent_bindings; scope jsonb; origin text;
BEGIN
 SELECT * INTO b FROM analytics.website_consent_bindings WHERE id=p_binding;
 IF auth.uid() IS NULL OR NOT coalesce(public.can_manage_unit_configuration(b.unit),false) THEN RAISE insufficient_privilege; END IF;
 IF b.version IS DISTINCT FROM p_expected_version THEN RAISE serialization_failure USING MESSAGE='website_consent_conflict'; END IF;
 IF NOT coalesce(public.website_consent_binding_effective_internal(b),false) THEN RAISE invalid_parameter_value USING MESSAGE='website_consent_not_ready'; END IF;
 SELECT rtrim(o.data->>'DEFAULT_URL','/') INTO origin FROM public.units u JOIN public.organizations o ON o.id=u.organization WHERE u.id=b.unit;
 IF origin IS NULL OR origin !~ '^https://[a-z0-9.-]+(:[0-9]+)?$' THEN RAISE invalid_parameter_value USING MESSAGE='website_consent_service_origin_missing'; END IF;
 scope:=public.unit_measurement_consent_scope_internal(b.unit);
 RETURN jsonb_build_object('schemaVersion',1,'serviceOrigin',origin,'websiteOrigin',b.website_origin,
  'binding',jsonb_build_object('id',b.id,'version',b.version),'providerConfig',b.provider_config||
   jsonb_build_object('organization',scope->'organization','unit',b.unit,'consentRevision',b.confirmed_revision,'origin',b.website_origin));
END $$;
REVOKE ALL ON FUNCTION public.export_unit_website_consent_binding(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.export_unit_website_consent_binding(uuid,bigint) TO authenticated;
CREATE SCHEMA IF NOT EXISTS analytics;
REVOKE ALL ON SCHEMA analytics FROM PUBLIC,anon,authenticated,service_role;

-- Platform deployment permission is distinct from administrator-owned switches.
CREATE TABLE IF NOT EXISTS analytics.organization_policy (
 organization bigint PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE,
 enabled boolean NOT NULL DEFAULT false,
 revision bigint NOT NULL CHECK(revision>0),
 changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 operator text NOT NULL CHECK(length(btrim(operator))>0),
 reason text NOT NULL CHECK(length(btrim(reason))>0)
);
-- Runtime code is authored by Unit managers, so each Unit has its own site.
CREATE TABLE IF NOT EXISTS analytics.unit_runtime (
 unit bigint PRIMARY KEY REFERENCES public.units(id) ON DELETE CASCADE,
 runtime_origin text NOT NULL UNIQUE CHECK(runtime_origin ~ '^https://[a-z0-9][a-z0-9-]{0,61}[a-z0-9]\.pages\.dev$'),
 runtime_profile text NOT NULL CHECK(runtime_profile='gtm-v1'),
 parent_origins text[] NOT NULL CHECK(cardinality(parent_origins)>0),
 collector_origins text[] NOT NULL DEFAULT '{}',
 revision bigint NOT NULL CHECK(revision>0),
 changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 operator text NOT NULL CHECK(length(btrim(operator))>0),
 reason text NOT NULL CHECK(length(btrim(reason))>0)
);
ALTER TABLE analytics.unit_runtime ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON analytics.unit_runtime FROM PUBLIC,anon,authenticated,service_role;

ALTER TABLE analytics.organization_policy ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON analytics.organization_policy FROM PUBLIC,anon,authenticated,service_role;

-- Shared redaction for public/catalog Unit projections. Manager reads retain
-- the single canonical Unit configuration; browsers never get raw script data.
CREATE OR REPLACE FUNCTION public.form_measurement_unit_data_internal(p_unit bigint,p_data jsonb)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT CASE WHEN public.can_manage_unit_configuration(p_unit) THEN jsonb_build_object('measurement_consent_version',1,'measurement_consent_bridge',false)||coalesce(p_data,'{}'::jsonb)
  ELSE (jsonb_build_object('measurement_consent_version',1,'measurement_consent_bridge',false)||coalesce(p_data,'{}'::jsonb))-'measurement_gtm_container'-'measurement_scripts' END;
$$;
REVOKE ALL ON FUNCTION public.form_measurement_unit_data_internal(bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- One semantic notice owner for admin exports and public form policy.
CREATE OR REPLACE FUNCTION public.unit_measurement_consent_scope_internal(p_unit bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT jsonb_build_object('organization',u.organization,'unit',u.id,'consentRevision',md5(jsonb_build_array(1,u.organization,u.id,u.data->'measurement_gtm_container',
   u.data->'measurement_scripts',u.data->'measurement_privacy_url',u.data->'measurement_consent_title',
   u.data->'measurement_consent_text',coalesce(u.data->'measurement_consent_version','1'::jsonb),
   r.runtime_profile,r.collector_origins,jsonb_build_array('analytics','marketing'))::text))
 FROM public.units u LEFT JOIN analytics.unit_runtime r ON r.unit=u.id WHERE u.id=p_unit;
$$;
REVOKE ALL ON FUNCTION public.unit_measurement_consent_scope_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- consent_required denotes the required notice/choice controls, not an execution gate.
-- required_purposes describes reported choices; neither purpose must be granted to run.
-- Single status owner. Configuration belongs to Unit; forms contain only intent.
CREATE OR REPLACE FUNCTION public.form_measurement_status_internal(p_form bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 WITH scope AS MATERIALIZED (
  SELECT coalesce(public.normalize_form_metadata_internal(f.data)#>'{analytics,enabled}'='true'::jsonb,false) requested,
   coalesce(org.data->'FORM_MEASUREMENT_ENABLED'='true'::jsonb,false) organization_enabled,
   coalesce(u.data->'measurement_enabled'='true'::jsonb,false) unit_enabled,
   coalesce(length(u.data->>'measurement_privacy_url') BETWEEN 1 AND 2048
    AND (u.data->>'measurement_privacy_url') ~ (public.configuration_settings_contract_internal_v1()#>>'{unit,measurement_privacy_url,pattern}'),false) privacy_policy_valid,
   coalesce(p.enabled,false) allowed,coalesce(p.revision,0) revision,
   coalesce(nullif(btrim(u.data->>'measurement_gtm_container'),''),nullif(u.data->>'measurement_scripts','')) IS NOT NULL destination,
   public.form_measurement_runtime_supported_internal(r.runtime_profile,r.runtime_origin,r.parent_origins)
    AND NOT public.is_demo_occasion(f.occasion) supported
  FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
  JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
  JOIN public.organizations org ON org.id=o.organization
  LEFT JOIN analytics.organization_policy p ON p.organization=o.organization
  LEFT JOIN analytics.unit_runtime r ON r.unit=u.id
  WHERE f.id=p_form
 ) SELECT jsonb_build_object('requested_enabled',requested,'organization_allowed',allowed,
  'organization_enabled',organization_enabled,'unit_enabled',unit_enabled,
  'runtime_supported',supported,'eligible',requested AND allowed AND organization_enabled AND unit_enabled AND destination AND supported AND privacy_policy_valid,
  'policy_revision',revision,'consent_required',true,'enhanced_conversions_unavailable',false,
  'blocked_reasons',to_jsonb(array_remove(ARRAY[
   CASE WHEN NOT requested THEN 'disabled' END,
   CASE WHEN NOT allowed THEN 'organization_not_enabled' END,
   CASE WHEN NOT organization_enabled THEN 'organization_disabled' END,
   CASE WHEN NOT unit_enabled THEN 'unit_disabled' END,
   CASE WHEN NOT supported THEN 'runtime_unavailable' END,
   CASE WHEN NOT destination THEN 'no_destination' END,
   CASE WHEN NOT privacy_policy_valid THEN 'no_privacy_policy' END],NULL))) FROM scope;
$$;
REVOKE ALL ON FUNCTION public.form_measurement_status_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.form_measurement_runtime_internal(p_form bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 WITH status AS MATERIALIZED (
  SELECT public.form_measurement_status_internal(p_form) AS s
 )
 SELECT jsonb_build_object('enabled',s->'requested_enabled','organization_allowed',s->'organization_allowed',
  'runtime_supported',s->'runtime_supported','eligible',s->'eligible','organization',o.organization,'unit',u.id,
  'runtime_origin',CASE WHEN s->'eligible'='true'::jsonb THEN r.runtime_origin END,
  'measurement_consent_bridge',coalesce(u.data->'measurement_consent_bridge'='true'::jsonb,false),
  'privacy_url',CASE WHEN s->'eligible'='true'::jsonb THEN u.data->>'measurement_privacy_url' END,
  'consent_notice',CASE WHEN s->'eligible'='true'::jsonb THEN jsonb_build_object('layout',coalesce(u.data->>'measurement_consent_layout','bar'),
   'title',nullif(btrim(u.data->>'measurement_consent_title'),''),'text',nullif(btrim(u.data->>'measurement_consent_text'),'')) END,
  'approved_hosts',CASE WHEN s->'eligible'='true'::jsonb THEN to_jsonb(r.parent_origins) ELSE '[]'::jsonb END,
  -- Stable notice/processing scope, independent of runtime deployment and approved hosts.
  -- Changes behind an unchanged GTM ID/privacy URL require a consent-version increment.
  'consent_revision',public.unit_measurement_consent_scope_internal(u.id)->>'consentRevision',
  'website_consent_bindings',public.website_consent_bindings_policy_internal(u.id),
  'measurement_protocol',3,'form_link',f.link,'profile',r.runtime_profile,'required_purposes',jsonb_build_array('analytics','marketing'),
  'enhanced_conversions_unavailable',false,
  -- Append the opt-in only when enabled to preserve existing saved choices.
  'processing_revision',md5((jsonb_build_array(3,o.organization,u.id,u.data->'measurement_gtm_container',u.data->'measurement_scripts',
   u.data->'measurement_privacy_url',coalesce(u.data->'measurement_consent_version','1'::jsonb),r.runtime_profile,r.runtime_origin,
   r.parent_origins,r.collector_origins,r.revision,s->'policy_revision',u.data->'measurement_enabled',
   org.data->'FORM_MEASUREMENT_ENABLED',s->'requested_enabled')
   ||CASE WHEN u.data->'measurement_consent_bridge'='true'::jsonb THEN jsonb_build_array(true) ELSE '[]'::jsonb END
   ||CASE WHEN nullif(u.data->>'measurement_consent_title','') IS NOT NULL OR nullif(u.data->>'measurement_consent_text','') IS NOT NULL
     THEN jsonb_build_array(u.data->'measurement_consent_title',u.data->'measurement_consent_text') ELSE '[]'::jsonb END
   ||CASE WHEN public.website_consent_bindings_policy_internal(u.id) <> '[]'::jsonb
     THEN jsonb_build_array(public.website_consent_bindings_policy_internal(u.id)) ELSE '[]'::jsonb END)::text),
  'configuration_revision',md5(jsonb_build_array(u.data->'measurement_gtm_container',u.data->'measurement_scripts',
   u.data->'measurement_enabled',org.data->'FORM_MEASUREMENT_ENABLED',s->'requested_enabled')::text),
  'runtime_revision',coalesce(r.revision,0),'policy_revision',s->'policy_revision','valid_for_seconds',60,'consent_required',true)
 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
 JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
 JOIN public.organizations org ON org.id=o.organization
 LEFT JOIN analytics.organization_policy p ON p.organization=o.organization
  LEFT JOIN analytics.unit_runtime r ON r.unit=u.id
 CROSS JOIN status
 WHERE f.id=p_form;
$$;
REVOKE ALL ON FUNCTION public.form_measurement_runtime_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

